package org.sleepwell.app;

import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;

public class WalkSessionTest {
    private static final class Fake implements WalkSession.Port {WalkSteps.Mode mode=WalkSteps.Mode.DETECTOR;boolean allowed=true,registered=true,fail,failClose,failPermission;long now=100;WalkSession.Sink sink;int opens,closes;public WalkSteps.Mode mode(){return mode;}public boolean allowed(){if(failPermission)throw new SecurityException("revoked");return allowed;}public long now(){return now;}public boolean begin(WalkSession.Sink sink){opens++;if(fail)throw new IllegalStateException("registration");this.sink=sink;return registered;}public void close(){closes++;if(failClose)throw new IllegalStateException("release");sink=null;}}
    private static final class Effects implements WalkSession.Effects {String run="run";int unit=2,solved;List<Integer> progress=new ArrayList<>();public boolean current(String run,int unit){return this.run.equals(run)&&this.unit==unit;}public void progress(String run,int unit,int earned){assertTrue(current(run,unit));progress.add(earned);}public void solved(String run,int unit){assertTrue(current(run,unit));solved++;}}
    private WalkSession session(Fake fake,Effects effects,int earned){return new WalkSession(fake,effects,"run",2,5,earned);}
    @Test public void detectorCountsOnlyValidFreshDistinctStepEvents(){Fake fake=new Fake();Effects effects=new Effects();WalkSession session=session(fake,effects,0);session.resume();WalkSession.Sink callback=fake.sink;callback.sample(99,1);callback.sample(100,2);callback.sample(100,Double.NaN);assertEquals(0,session.earned());callback.sample(101,1);callback.sample(101,1);callback.sample(100,1);callback.sample(102,-1);assertEquals(1,session.earned());for(int n=102;n<=105;n++)callback.sample(n,1);assertEquals(5,session.earned());assertEquals(List.of(1,2,3,4,5),effects.progress);assertEquals(1,effects.solved);callback.sample(106,1);assertEquals(1,effects.solved);assertNull(fake.sink);}
    @Test public void counterUsesAnActivationBaselineInsteadOfBootTotal(){Fake fake=new Fake();fake.mode=WalkSteps.Mode.COUNTER;Effects effects=new Effects();WalkSession session=session(fake,effects,0);session.resume();fake.sink.sample(101,5000);assertEquals(0,session.earned());fake.sink.sample(102,5003);assertEquals(3,session.earned());fake.sink.sample(103,5003);assertEquals(3,session.earned());fake.sink.sample(104,5005);assertEquals(1,effects.solved);assertEquals(5,session.earned());}
    @Test public void counterResetAndResumeDoNotCountPausedOrPriorBootSteps(){Fake fake=new Fake();fake.mode=WalkSteps.Mode.COUNTER;Effects effects=new Effects();WalkSession session=session(fake,effects,0);session.resume();fake.sink.sample(101,5000);fake.sink.sample(102,5002);assertEquals(2,session.earned());WalkSession.Sink stale=fake.sink;session.close();stale.sample(103,6000);assertEquals(2,session.earned());fake.now=200;session.resume();fake.sink.sample(201,7000);assertEquals(2,session.earned());fake.sink.sample(202,10);assertEquals(2,session.earned());fake.sink.sample(203,12);assertEquals(4,session.earned());}
    @Test public void callbackGenerationAndOccurrenceFencesSurviveLifecycle(){Fake fake=new Fake();Effects effects=new Effects();WalkSession session=session(fake,effects,0);session.resume();WalkSession.Sink stale=fake.sink;session.close();fake.now=300;session.resume();stale.sample(301,1);assertEquals(0,session.earned());fake.sink.sample(301,1);assertEquals(1,session.earned());effects.run="other-run";WalkSession.Sink current=fake.sink;current.sample(302,1);assertEquals(1,session.earned());effects.run="run";effects.unit=3;current.sample(303,1);assertEquals(1,session.earned());}
    @Test public void lostOccurrenceReleasesAndCannotReviveAnOldCallback(){Fake fake=new Fake();Effects effects=new Effects();WalkSession session=session(fake,effects,0);session.resume();WalkSession.Sink old=fake.sink;old.sample(101,1);int before=fake.closes;effects.run="stopped";old.sample(102,1);assertEquals(WalkSession.State.CLOSED,session.state());assertEquals(before+1,fake.closes);assertNull(fake.sink);assertEquals(1,session.earned());effects.run="run";old.sample(103,1);assertEquals(1,session.earned());assertEquals(1,fake.opens);assertEquals(0,effects.solved);fake.now=200;session.resume();old.sample(201,1);assertEquals(1,session.earned());fake.sink.sample(201,1);assertEquals(2,session.earned());assertEquals(2,fake.opens);}
    @Test public void changedTaskReleasesEvenWhenTheOccurrenceStillMatches(){Fake fake=new Fake();Effects effects=new Effects();WalkSession session=session(fake,effects,0);session.resume();WalkSession.Sink old=fake.sink;effects.unit=3;old.sample(101,1);assertEquals(WalkSession.State.CLOSED,session.state());assertNull(fake.sink);effects.unit=2;old.sample(102,1);assertEquals(0,session.earned());assertTrue(effects.progress.isEmpty());assertEquals(0,effects.solved);}
    @Test public void missingPermissionOrSensorDoesNotRegister(){for(boolean missingPermission:new boolean[]{true,false}){Fake fake=new Fake();fake.allowed=!missingPermission;fake.mode=missingPermission?WalkSteps.Mode.DETECTOR:WalkSteps.Mode.NONE;WalkSession session=session(fake,new Effects(),0);session.resume();assertEquals(missingPermission?WalkSession.State.PERMISSION:WalkSession.State.UNSUPPORTED,session.state());assertEquals(0,fake.opens);assertNull(fake.sink);}}
    @Test public void registrationFailureOffersAnErrorWithoutCompleting(){for(boolean throwsError:new boolean[]{true,false}){Fake fake=new Fake();fake.fail=throwsError;fake.registered=false;Effects effects=new Effects();WalkSession session=session(fake,effects,0);session.resume();assertEquals(WalkSession.State.ERROR,session.state());assertEquals(0,effects.solved);assertNull(fake.sink);}}
    @Test public void earnedProgressCanBeRestoredAndDoneIsDeliveredOnce(){Fake fake=new Fake();Effects effects=new Effects();WalkSession session=session(fake,effects,4);session.resume();fake.sink.sample(101,1);assertEquals(1,effects.solved);session.resume();assertEquals(1,effects.solved);WalkSession recovered=session(new Fake(),new Effects(),5);recovered.resume();assertEquals(WalkSession.State.DONE,recovered.state());}
    @Test public void releaseFailureCannotCrashOrRearmTheOwner(){Fake fake=new Fake();Effects effects=new Effects();WalkSession session=session(fake,effects,0);session.resume();WalkSession.Sink stale=fake.sink;fake.failClose=true;session.close();stale.sample(101,1);assertEquals(0,session.earned());session.resume();assertEquals(WalkSession.State.ERROR,session.state());assertEquals(1,fake.opens);assertEquals(0,effects.solved);}
    @Test public void failedUnregisterKeepsTheOwnedHandleForRetryWithoutRevivingCallbacks(){Fake fake=new Fake();Effects effects=new Effects();WalkSession session=session(fake,effects,0);session.resume();WalkSession.Sink stale=fake.sink;fake.failClose=true;session.close();assertSame(stale,fake.sink);stale.sample(101,1);assertEquals(0,session.earned());fake.failClose=false;session.close();assertNull(fake.sink);fake.now=200;session.resume();stale.sample(201,1);assertEquals(0,session.earned());fake.sink.sample(201,1);assertEquals(1,session.earned());assertEquals(2,fake.opens);}
    @Test public void genuineWalkIsOneRoutineUnitAndCannotSkipTheNextTask(){ChallengeRoutine.Task walk=new ChallengeRoutine.Task("Walk",1,20);ChallengeRoutine routine=new ChallengeRoutine(List.of(walk,new ChallengeRoutine.Task("Math",2)));assertEquals(1,walk.units());assertEquals("20 steps",walk.detail());assertEquals("Math",routine.at(routine.advance(0,0)).task.type);assertEquals(3,routine.units());assertEquals("Math",ChallengeRoutine.legacy("Walk",3).at(0).task.type);}
    @Test public void targetBoundsAndWholeStepEventsAreEnforced(){assertThrows(IllegalArgumentException.class,()->new WalkSteps(4,0));assertThrows(IllegalArgumentException.class,()->new WalkSteps(101,0));assertThrows(IllegalArgumentException.class,()->new ChallengeRoutine.Task("Walk",2,10));WalkSteps steps=new WalkSteps(5,-2);steps.arm(WalkSteps.Mode.COUNTER,0);assertFalse(steps.sample(1,3.5));assertFalse(steps.sample(2,Double.POSITIVE_INFINITY));assertEquals(0,steps.earned());}
    @Test public void permissionRevocationRejectsQueuedStepsAndReleasesBeforeNotification(){
        Fake fake=new Fake();List<WalkSession.State> unavailable=new ArrayList<>();Effects original=new Effects();
        WalkSession session=new WalkSession(fake,new WalkSession.Effects(){public boolean current(String run,int unit){return original.current(run,unit);}public void progress(String run,int unit,int earned){original.progress(run,unit,earned);}public void solved(String run,int unit){original.solved(run,unit);}public void unavailable(String run,int unit,WalkSession.State state){assertNull("Listener released before fallback notice",fake.sink);unavailable.add(state);}},"run",2,5,0);
        session.resume();WalkSession.Sink queued=fake.sink;queued.sample(101,1);fake.allowed=false;queued.sample(102,1);queued.sample(103,1);
        assertEquals(1,session.earned());assertEquals(List.of(1),original.progress);assertEquals(0,original.solved);assertEquals(List.of(WalkSession.State.PERMISSION),unavailable);assertEquals(WalkSession.State.PERMISSION,session.state());
    }
    @Test public void permissionExceptionDuringCallbackIsContainedWithoutCompletion(){Fake fake=new Fake();Effects effects=new Effects();WalkSession session=session(fake,effects,0);session.resume();WalkSession.Sink queued=fake.sink;fake.failPermission=true;queued.sample(101,1);assertEquals(WalkSession.State.PERMISSION,session.state());assertNull(fake.sink);assertEquals(0,session.earned());assertEquals(0,effects.solved);}
    @Test public void explicitFallbackRevokesAllQueuedCallbacksAndCanRetryUnregister(){Fake fake=new Fake();Effects effects=new Effects();WalkSession session=session(fake,effects,0);session.resume();WalkSession.Sink queued=fake.sink;fake.failClose=true;assertFalse(session.stopForFallback());queued.sample(101,1);assertEquals(0,session.earned());fake.failClose=false;assertTrue(session.stopForFallback());assertNull(fake.sink);queued.sample(102,1);assertEquals(0,effects.solved);assertEquals(1,fake.opens);}
    @Test public void revokedPermissionWithFailedReleaseRetainsRetryHandleAndCannotRearm(){
        Fake fake=new Fake();Effects effects=new Effects();int[] notifications={0};
        WalkSession session=new WalkSession(fake,new WalkSession.Effects(){public boolean current(String run,int unit){return effects.current(run,unit);}public void progress(String run,int unit,int earned){effects.progress(run,unit,earned);}public void solved(String run,int unit){effects.solved(run,unit);}public void unavailable(String run,int unit,WalkSession.State state){notifications[0]++;assertEquals(WalkSession.State.PERMISSION,state);}},"run",2,5,0);
        session.resume();WalkSession.Sink queued=fake.sink;fake.allowed=false;fake.failClose=true;queued.sample(101,1);assertEquals(1,notifications[0]);assertSame(queued,fake.sink);assertFalse(session.stopForFallback());session.resume();assertEquals(WalkSession.State.ERROR,session.state());assertEquals("Unconfirmed owner cannot register a replacement",1,fake.opens);queued.sample(102,1);assertEquals(0,session.earned());fake.failClose=false;assertTrue(session.stopForFallback());assertNull(fake.sink);assertEquals(0,effects.solved);
    }
}
